        "meet" -> meet(S(O(i)["decision"]), S(O(i)["signal"]))
        "pep" -> {
            val d = S(O(i)["decision"])
            if (d == "allow") true else if (d == "deny") false else {
                val ans = O(i)["answer"]?.let { O(it) }; val ctx = O(O(i)["ctx"])
                ans != null && ans["valid"] == true && listOf("policy_digest", "action_digest", "history_head").all { ans[it] == ctx[it] }
            }
        }
        "commit" -> mk("commit" to b64(sha("pca-goal:v3:commit:" + S(O(i)["goal_digest"]) + ":" + S(O(i)["policy_digest"]) + ":" + S(O(i)["salt"]))), "opens_other_goal" to false)
        "claim" -> { val rp = O(i)["replayed_ppm"]; if (rp != null && N(rp) < N(O(i)["min_ppm"])) meet(S(O(i)["base"]), "escalate") else O(i)["base"] }
        else -> throw IllegalStateException("unknown fn " + v["fn"])
    }
}

/** Replays every vector of a directory: (vectors, probes, disagreements). */
fun replay(dir: String): Triple<Int, Int, List<String>> {
    val d = File(dir)
    val names = d.listFiles()!!.map { it.name }.filter { it.endsWith(".json") && it != "index.json" }.sorted()
    val bad = ArrayList<String>(); var probes = 0
    for (n in names) {
        val v = O(P(File(d, n).readText(Charsets.UTF_8)).v()); val id = S(v["id"])
        if (S(v["kind"]) == "fn") { if (canon(runFn(v)) != canon(v["expect"])) bad.add(id); continue }
        val goal = O(v["goal"]); val ont = O(v["ontology"])
        val sel = v["sel"]
        if (sel != null && canon(expandSel(O(O(sel)["goal"]), ont, O(O(sel)["catalog"]))) != canon(goal)) bad.add("$id:expansion")
        if (goalDigest(goal) != S(v["goal_digest"])) bad.add("$id:goal_digest")
        if (O(v["compile"])["ok"] != true) continue
        if (hashCanon(lower(ont, goal)) != S(v["policy_digest"])) bad.add("$id:policy_digest")
        for ((i, pr) in A(v["probes"]).withIndex()) {
            probes++; val p = O(pr)
            if (canon(decide(goal, ont, O(p["action"]), O(p["history"]))) != canon(p["expect"])) bad.add("$id#$i")
        }
    }
    return Triple(names.size, probes, bad)
}

fun main(args: Array<String>) {
    val (n, probes, bad) = replay(args[0])
    println("kotlin: $n vectors, $probes probes, ${bad.size} disagreements")
    bad.take(20).forEach { println("   $it") }
    if (bad.isNotEmpty() || n == 0) System.exit(1)
}
